fn main() -> Int {
  let grades: Map[Str,Int] = Map[Str,Int].new();
  grades.insert("Ana", 88);
  grades.insert("Ben", 76);
  grades.insert("Cara", 94);

  match grades.get("Ben") {
    Some(g) -> io.println("Ben: " + string.int_to_str(g));
    None -> io.println("Ben: not found");
  }

  grades.insert("Ben", 80);

  match grades.get("Ben") {
    Some(g) -> io.println("Ben updated: " + string.int_to_str(g));
    None -> io.println("Ben: not found");
  }

  return 0;
}
